using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using ModelContextProtocol;

var builder = Host.CreateApplicationBuilder(args);

// Register your own services into DI — MCP tools receive them via constructor injection.
builder.Services.AddHttpClient<WeatherApiClient>(client =>
{
    client.BaseAddress = new Uri("https://api.open-meteo.com/");
});

builder.Services
    .AddMcpServer()
    .WithStdioServerTransport()
    // Scans the assembly for classes containing [McpServerTool] methods
    .WithToolsFromAssembly();

await builder.Build().RunAsync();

using System.Net.Http.Json;
using System.Text.Json.Serialization;

/// <summary>
/// Typed HttpClient for the Open-Meteo weather API.
/// Registered in DI and injected into tool methods automatically.
/// </summary>
public sealed class WeatherApiClient(HttpClient http)
{
    public async Task<WeatherResponse?> GetCurrentWeatherAsync(
        double latitude, double longitude, CancellationToken ct = default)
    {
        var url = $"v1/forecast?latitude={latitude}&longitude={longitude}"
                + "&current_weather=true";
        return await http.GetFromJsonAsync<WeatherResponse>(url, ct);
    }
}

public sealed class WeatherResponse
{
    [JsonPropertyName("current_weather")]
    public CurrentWeather? CurrentWeather { get; set; }
}

public sealed class CurrentWeather
{
    [JsonPropertyName("temperature")]
    public double Temperature { get; set; }

    [JsonPropertyName("windspeed")]
    public double WindSpeed { get; set; }

    [JsonPropertyName("weathercode")]
    public int WeatherCode { get; set; }
}

using ModelContextProtocol.Server;
using System.ComponentModel;

/// <summary>
/// MCP tool class. The SDK discovers methods marked with [McpServerTool].
/// Constructor parameters and method parameters that are DI-registered services
/// are injected automatically; remaining parameters become the tool's input schema.
/// </summary>
[McpServerToolType]
public static class WeatherTools
{
    [McpServerTool, Description("Get current weather for a location.")]
    public static async Task<string> GetCurrentWeather(
        WeatherApiClient weatherClient,
        [Description("Latitude of the location")]  double latitude,
        [Description("Longitude of the location")] double longitude,
        CancellationToken ct)
    {
        var result = await weatherClient.GetCurrentWeatherAsync(latitude, longitude, ct);

        if (result?.CurrentWeather is not { } weather)
            return "Unable to retrieve weather data.";

        return $"Temperature: {weather.Temperature}°C, "
             + $"Wind: {weather.WindSpeed} km/h, "
             + $"Code: {weather.WeatherCode}";
    }
}

